args.streamContent:
import { Playfair_Display, Roboto } from 'next/font/google';

const playfair = Playfair_Display({
  subsets: ['latin'],
  variable: '--font-playfair',
});

const roboto = Roboto({
  weight: ['400', '500', '700'],
  subsets: ['latin'],
  variable: '--font-roboto',
});

export default function BlogHeader() {
  return (
    <header className={`${playfair.variable} ${roboto.variable}`} style={{ fontFamily: 'var(--font-playfair), serif' }}>
      <h1 style={{ fontFamily: 'var(--font-playfair), serif' }}>My Personal Blog</h1>
      <p style={{ fontFamily: 'var(--font-roboto), sans-serif' }}>Thoughts, ideas, and musings</p>
    </header>
  );
}

